 => 'अच्छी स्थिति का राहु साहसी महत्वाकांक्षा, राजनीति, तकनीक, विदेश व्यापार या मीडिया में सफलता और अचानक लाभ देता है। आप लीक से हटकर सोचते हैं और नए अवसर जल्दी पकड़ लेते हैं।', 'weak' => 'पीड़ित राहु भ्रम, भय, व्यसन, दूसरों से धोखा और अचानक झटके देता है। मानसिक अशांति, त्वचा की समस्या और छिपे शत्रुओं से परेशानी संभव है, इसलिए स्पष्टता और ईमानदार व्यवहार आवश्यक है।', 'dasha' => 'राहु की महादशा अठारह वर्ष की होती है और अचानक बदलाव लाती है: विदेश यात्रा, नए क्षेत्र, तेज़ उन्नति या अप्रत्याशित मोड़। इसके फल बहुत हद तक उस भाव, राशि और राशि-स्वामी पर निर्भर करते हैं जिसमें यह बैठा है।', 'remedy' => 'माँ दुर्गा या सरस्वती की पूजा करें, धार्मिक स्थानों पर सिर ढक कर रखें और नारियल, जौ या गहरे रंग के वस्त्र का दान करें। शराब और शॉर्टकट से बचें; सत्य पर टिके रहना राहु को नियंत्रण में रखता है।', 'deity' => 'माँ दुर्गा', 'day' => 'शनिवार', 'color' => 'धूसर, धुएँ जैसा नीला', 'gem' => 'गोमेद', 'metal' => 'सीसा', 'grain' => 'जौ', 'number' => '4', 'mantra' => 'ॐ राहवे नमः'], 'Ketu' => ['sig' => 'केतु चंद्रमा का दक्षिणी पात है: वैराग्य, आध्यात्म, पूर्वजन्म के कौशल और अचानक अंतर्दृष्टि। यह अंतर्ज्ञान, शोध, गुप्त विद्या, पुत्र, नाना-नानी और कुत्ते जैसे छोटे जीवों का कारक है। केतु जिस भाव में होता है वहाँ अचानक घटनाएँ और कुछ कमी का अनुभव देता है, जिससे आप गहराई में देखना सीखते हैं।', 'strong' => 'अच्छी स्थिति का केतु तीक्ष्ण अंतर्ज्ञान, आध्यात्मिक गहराई, शोध क्षमता और लोभ से मुक्ति देता है। पूर्वजन्म की प्रतिभाएँ सहजता से प्रकट होती हैं और जो अब काम का नहीं उसे आप छोड़ पाते हैं।', 'weak' => 'पीड़ित केतु भ्रम, रुचि की कमी, अकेलापन, अचानक चोट और कठिनाई से पहचाने जाने वाले रोग दे सकता है। जल्दबाज़ी या उदासीनता में लिए निर्णय हानि दे सकते हैं।', 'dasha' => 'केतु की महादशा सात वर्ष की होती है और अक्सर मन को भीतर की ओर मोड़ती है: आध्यात्म, शोध, तीर्थयात्रा और मोह छोड़ना। यह अचानक बदलाव ला सकती है और आंतरिक विकास व अध्ययन के लिए सबसे अच्छी तरह उपयोग होती है।', 'remedy' => 'गणेश जी की पूजा करें, कुत्तों को भोजन दें और मंदिर में काला-सफेद कंबल या तिल दान करें। केसर का तिलक और नियमित ध्यान केतु को शांत करते हैं।', 'deity' => 'गणेश जी', 'day' => 'मंगलवार', 'color' => 'बहुरंगी, धूसर', 'gem' => 'लहसुनिया', 'metal' => 'मिश्र धातु', 'grain' => 'तिल', 'number' => '7', 'mantra' => 'ॐ केतवे नमः']],
'sign' => ['Aries' => ['el' => 'अग्नि', 'mod' => 'चर', 'body' => 'सिर', 'nature' => 'मेष राशिचक्र की पहली राशि है: अग्नि तत्व, साहसी और अग्रणी, जिसका प्रतीक मेढ़ा है। इसे नई शुरुआत, गति और चुनौतियाँ प्रिय हैं।', 'lagna' => 'मेष लग्न होने से आपका शरीर सक्रिय और ऊर्जावान तथा व्यक्तित्व सीधा और साहसी है। आप नेतृत्व करना, तेज़ी से काम करना और साफ़ बोलना पसंद करते हैं, इंतज़ार आपको नहीं भाता। चेहरे पर दृढ़ता दिखती है और सिर स्वास्थ्य की दृष्टि से संवेदनशील है। धैर्य सीखना और शुरू किया काम पूरा करना आपकी ऊर्जा को सच्ची सफलता में बदलता है।', 'moon' => 'मेष राशि में चंद्रमा होने से आपकी भावनाएँ तेज़, गर्मजोशी भरी और ईमानदार हैं। आप तुरंत प्रतिक्रिया देते हैं, जल्दी गुस्सा होते हैं पर जल्दी माफ़ भी करते हैं, और कुछ करते हुए सबसे खुश रहते हैं। आपको स्वतंत्रता और उत्साह चाहिए; बंधन और एकरसता आपको बेचैन करते हैं।'], 'Taurus' => ['el' => 'पृथ्वी', 'mod' => 'स्थिर', 'body' => 'चेहरा और गला', 'nature' => 'वृषभ स्थिर, व्यावहारिक और सुख-प्रिय राशि है, जिसका प्रतीक बैल है। यह सुरक्षा, आराम, सौंदर्य और निष्ठा को महत्व देती है।', 'lagna' => 'वृषभ लग्न होने से आपका स्वभाव शांत और स्थिर तथा रूप सुखद और सुगठित है। आप धैर्यवान, व्यावहारिक और भरोसेमंद हैं और अच्छा भोजन, संगीत व आराम पसंद करते हैं। अचानक बदलाव पसंद नहीं और एक बार निर्णय लेने पर ज़िद्दी हो सकते हैं। गले और गर्दन का ध्यान रखें; नियमित दिनचर्या आपको स्वस्थ रखती है।', 'moon' => 'वृषभ राशि में, जो चंद्रमा की उच्च राशि है, आपकी भावनाएँ स्थिर, निष्ठावान और धरातल से जुड़ी हैं। घर, प्रकृति, अच्छा भोजन और आर्थिक सुरक्षा में आपको शांति मिलती है। एक बार जुड़ने पर आप जुड़े रहते हैं और प्रियजनों की व्यावहारिक, भरोसेमंद देखभाल करते हैं।'], 'Gemini' => ['el' => 'वायु', 'mod' => 'द्विस्वभाव', 'body' => 'भुजाएँ, कंधे और फेफड़े', 'nature' => 'मिथुन जिज्ञासु, संवादप्रिय और बहुमुखी राशि है, जिसका प्रतीक जुड़वाँ हैं। इसे जानकारी, बातचीत, यात्रा और विविधता पसंद है।', 'lagna' => 'मिथुन लग्न होने से आप हाज़िरजवाब, बातूनी और रूप व व्यवहार में युवा दिखते हैं। आप जल्दी सीखते हैं, लोगों से आसानी से घुलमिल जाते हैं और एक साथ कई काम संभाल सकते हैं। बेचैनी और बिखरे प्रयास आपकी चुनौती हैं। नसों, फेफड़ों और हाथों का ध्यान रखें; एकाग्रता आपकी अनेक प्रतिभाओं को निखारती है।', 'moon' => 'मिथुन राशि में चंद्रमा होने से आपका मन चंचल, जिज्ञासु और हमेशा नए विचार खोजता है। आप भावनाओं को बात करके और सोचकर समझते हैं और संतोष के लिए मानसिक प्रेरणा चाहिए। मूड जल्दी बदलता है और मित्र व बातचीत आपकी खुशी में बड़ी भूमिका निभाते हैं।'], 'Cancer' => ['el' => 'जल', 'mod' => 'चर', 'body' => 'छाती और पेट', 'nature' => 'कर्क स्नेही, संवेदनशील और रक्षक राशि है, जिसका प्रतीक केकड़ा है। यह घर, परिवार, स्मृति और भावनात्मक सुरक्षा को महत्व देती है।', 'lagna' => 'कर्क लग्न होने से आपका स्वभाव कोमल और स्नेही तथा चेहरा सौम्य है। परिवार, घर और भावनात्मक सुरक्षा आपके जीवन के केंद्र में हैं और आप प्रियजनों की पूरी शक्ति से रक्षा करते हैं। आप सहज-ज्ञानी और कल्पनाशील हैं पर मूडी या अति-संवेदनशील हो सकते हैं। छाती और पेट का ध्यान रखें; शांत घर आपको मज़बूत रखता है।', 'moon' => 'अपनी राशि कर्क में चंद्रमा होने से आपकी भावनाएँ गहरी, पोषण देने वाली और बहुत संवेदनशील हैं। आप दूसरों के मन को महसूस करते हैं और स्वाभाविक रूप से उनकी देखभाल करते हैं। घर और माता आपके लिए बहुत मायने रखते हैं और सर्वश्रेष्ठ प्रदर्शन के लिए भावनात्मक सुरक्षा चाहिए।'], 'Leo' => ['el' => 'अग्नि', 'mod' => 'स्थिर', 'body' => 'हृदय और रीढ़', 'nature' => 'सिंह राजसी, उदार और आत्मविश्वासी राशि है, जिसका प्रतीक शेर है। इसे पहचान, रचनात्मकता, नेतृत्व और निष्ठा प्रिय है।', 'lagna' => 'सिंह लग्न होने से आपका व्यक्तित्व गरिमामय, उपस्थिति प्रभावशाली और हृदय उदार है। आप नेतृत्व करना, सम्मान पाना और काम भव्य तरीके से करना पसंद करते हैं। अभिमान और प्रशंसा की चाह मतभेद पैदा कर सकती है, पर आपकी निष्ठा और गर्मजोशी लोगों का दिल जीत लेती है। हृदय और रीढ़ का ध्यान रखें; अपने से बड़ा उद्देश्य आपका सर्वश्रेष्ठ निकालता है।', 'moon' => 'सिंह राशि में चंद्रमा होने से आपकी भावनाएँ गर्मजोशी भरी, स्वाभिमानी और अभिव्यक्त होती हैं। आपको सराहना की ज़रूरत होती है और जो आपको महत्व देते हैं उन्हें आप उदारता से देते हैं। आहत अभिमान आपको गहराई से प्रभावित करता है; रचनात्मक अभिव्यक्ति और प्रियजनों की प्रशंसा आपको खुश रखती है।'], 'Virgo' => ['el' => 'पृथ्वी', 'mod' => 'द्विस्वभाव', 'body' => 'आँतें और पाचन', 'nature' => 'कन्या विश्लेषक, व्यावहारिक और सेवाभावी राशि है, जिसका प्रतीक कन्या है। यह सटीकता, स्वास्थ्य, व्यवस्था और उपयोगी काम को महत्व देती है।', 'lagna' => 'कन्या लग्न होने से आप साफ़-सुथरे, सावधान और बुद्धिमान हैं, युवा दिखावट और व्यावहारिक सोच के साथ। आप बारीकियाँ देखते हैं, समस्याएँ सुलझाते हैं और उपयोगी बनना पसंद करते हैं। चिंता और अपनी या दूसरों की अधिक आलोचना आपकी चुनौती है। पाचन और नसों का ध्यान रखें; स्वस्थ दिनचर्या आपको ठीक रखती है।', 'moon' => 'कन्या राशि में चंद्रमा होने से आपकी भावनाएँ देखभाल, सेवा और व्यावहारिक मदद के रूप में व्यक्त होती हैं। आप भावनाओं को खुलकर दिखाने की बजाय उनका विश्लेषण करते हैं और व्यवस्थित जीवन में सुरक्षित महसूस करते हैं। चिंता बढ़ सकती है, इसलिए दिनचर्या, अच्छी आदतें और उपयोगी काम मन को शांत करते हैं।'], 'Libra' => ['el' => 'वायु', 'mod' => 'चर', 'body' => 'गुर्दे और कमर', 'nature' => 'तुला संतुलित, कूटनीतिक और कलाप्रिय राशि है, जिसका प्रतीक तराज़ू है। यह सामंजस्य, साझेदारी, न्याय और सौंदर्य को महत्व देती है।', 'lagna' => 'तुला लग्न होने से आप शालीन, विनम्र और न्यायप्रिय हैं, सुखद रूप और अच्छी रुचि के साथ। साझेदारी आपके लिए बहुत मायने रखती है और आप दूसरों के साथ सबसे अच्छा काम करते हैं। अनिर्णय और सबको खुश रखने की इच्छा आपको धीमा कर सकती है। गुर्दे और कमर का ध्यान रखें; काम और आराम में संतुलन आपको स्वस्थ रखता है।', 'moon' => 'तुला राशि में चंद्रमा होने से आपकी मानसिक शांति सामंजस्य और अच्छे संबंधों पर निर्भर है। आप टकराव नापसंद करते हैं और सबको खुश रखने की कोशिश करते हैं, कभी-कभी अपनी कीमत पर। सौंदर्य, कला और प्रेमपूर्ण साथी आपके मन को पोषण देते हैं।'], 'Scorpio' => ['el' => 'जल', 'mod' => 'स्थिर', 'body' => 'प्रजनन और उत्सर्जन अंग', 'nature' => 'वृश्चिक गहन, रहस्यमय और परिवर्तनकारी राशि है, जिसका प्रतीक बिच्छू है। यह गहराई, निष्ठा, शोध और छिपी शक्ति को महत्व देती है।', 'lagna' => 'वृश्चिक लग्न होने से आपका व्यक्तित्व दृढ़ और आकर्षक तथा आँखें भेदने वाली हैं। आप दृढ़ निश्चयी, निजता-प्रिय और गहरे निष्ठावान हैं और मदद या नुकसान को शायद ही भूलते हैं। ईर्ष्या और संदेह आपकी चुनौती हैं। प्रजनन और उत्सर्जन तंत्र का ध्यान रखें; अपनी तीव्रता को शोध या उपचार में लगाने से बड़ी सफलता मिलती है।', 'moon' => 'वृश्चिक राशि में, जो चंद्रमा की नीच राशि है, भावनाएँ बहुत गहरी होती हैं और अक्सर छिपी रहती हैं। आप तीव्रता से महसूस करते हैं, धीरे-धीरे भरोसा करते हैं और चिंता या संदेह से प्रभावित हो सकते हैं। आध्यात्मिक साधना, भरोसेमंद संबंध और सार्थक काम आपको भावनात्मक बल देते हैं।'], 'Sagittarius' => ['el' => 'अग्नि', 'mod' => 'द्विस्वभाव', 'body' => 'कूल्हे, जाँघें और यकृत', 'nature' => 'धनु आशावादी, दार्शनिक और स्वतंत्रता-प्रिय राशि है, जिसका प्रतीक धनुर्धर है। यह सत्य, आस्था, ज्ञान और यात्रा को महत्व देती है।', 'lagna' => 'धनु लग्न होने से आप ईमानदार, प्रसन्नचित्त और आदर्शवादी हैं, अक्सर खुले और मिलनसार चेहरे के साथ। आपको ज्ञान, यात्रा, धर्म और दर्शन प्रिय हैं और आप मन की बात कह देते हैं। अति-आत्मविश्वास और रूखापन समस्या बना सकते हैं। कूल्हों, जाँघों और यकृत का ध्यान रखें; सार्थक लक्ष्य आपको ऊर्जावान रखता है।', 'moon' => 'धनु राशि में चंद्रमा होने से आपका मन आशावादी, उदार और अर्थ की खोज में रहता है। स्वतंत्रता, यात्रा, अध्ययन और आस्था में आप सबसे खुश रहते हैं। असफलताओं से जल्दी उबरते हैं, हालाँकि बेचैनी प्रतिबद्धता को कठिन बना सकती है।'], 'Capricorn' => ['el' => 'पृथ्वी', 'mod' => 'चर', 'body' => 'घुटने, हड्डियाँ और जोड़', 'nature' => 'मकर महत्वाकांक्षी, अनुशासित और व्यावहारिक राशि है, जिसका प्रतीक मगर है। यह ज़िम्मेदारी, प्रतिष्ठा, धैर्य और दीर्घकालिक सफलता को महत्व देती है।', 'lagna' => 'मकर लग्न होने से आप गंभीर, परिश्रमी और महत्वाकांक्षी हैं, अक्सर उम्र से अधिक परिपक्व दिखते हैं। आप जीवन को कदम-दर-कदम बनाते हैं और सफलता प्रायः तीस वर्ष के बाद बढ़ती है। निराशावाद और अधिक काम आपकी चुनौती हैं। घुटनों, हड्डियों और जोड़ों का ध्यान रखें; धैर्य आपकी सबसे बड़ी शक्ति है।', 'moon' => 'मकर राशि में चंद्रमा होने से आपकी भावनाएँ नियंत्रित, व्यावहारिक और ज़िम्मेदार हैं। आप प्रेम शब्दों से अधिक कर्तव्य और सहयोग से दिखाते हैं। कभी-कभी अकेलापन महसूस हो सकता है; उपलब्धि और सुरक्षा आपको भावनात्मक शांति देती है।'], 'Aquarius' => ['el' => 'वायु', 'mod' => 'स्थिर', 'body' => 'पिंडलियाँ, टखने और रक्त संचार', 'nature' => 'कुंभ मानवतावादी, मौलिक और स्वतंत्र राशि है, जिसका प्रतीक जल-वाहक है। यह मित्रता, विचार, समाज और प्रगति को महत्व देती है।', 'lagna' => 'कुंभ लग्न होने से आप मिलनसार, विचारशील और मौलिक हैं, समाज और नए विचारों में गहरी रुचि के साथ। आप स्वतंत्रता को महत्व देते हैं और बड़े समूहों में लोगों की मदद करना पसंद करते हैं। अलगाव और ज़िद दूरी पैदा कर सकते हैं। पिंडलियों, टखनों और रक्त संचार का ध्यान रखें; किसी उद्देश्य के लिए काम करना आपको गहरा संतोष देता है।', 'moon' => 'कुंभ राशि में चंद्रमा होने से आपकी भावनाएँ मित्रता, विचारों और दूसरों की सेवा में व्यक्त होती हैं। आपको स्थान और स्वतंत्रता चाहिए, और आप अलग-थलग दिख सकते हैं जबकि मन से बहुत परवाह करते हैं। सामूहिक गतिविधियाँ और सार्थक उद्देश्य आपके मन को खुश रखते हैं।'], 'Pisces' => ['el' => 'जल', 'mod' => 'द्विस्वभाव', 'body' => 'पैर और रोग-प्रतिरोधक क्षमता', 'nature' => 'मीन करुणामय, कल्पनाशील और आध्यात्मिक राशि है, जिसका प्रतीक दो मछलियाँ हैं। यह आस्था, दया, कला और आंतरिक शांति को महत्व देती है।', 'lagna' => 'मीन लग्न होने से आप कोमल, दयालु और कल्पनाशील हैं, सौम्य और स्वप्निल आँखों के साथ। आप दूसरों के दुख के प्रति संवेदनशील हैं और अक्सर आध्यात्म, कला या उपचार की ओर आकर्षित होते हैं। पलायनवाद और सीमाओं की कमी आपकी चुनौती हैं। पैरों और रोग-प्रतिरोधक क्षमता का ध्यान रखें; आध्यात्मिक दिनचर्या आपको स्थिर रखती है।', 'moon' => 'मीन राशि में चंद्रमा होने से आपकी भावनाएँ कोमल, सहज-ज्ञानी और करुणामय हैं। आप आसपास के मन को आत्मसात कर लेते हैं, इसलिए शांत संगति और आध्यात्मिक साधना महत्वपूर्ण है। कल्पना प्रबल है और आप प्रियजनों को निःस्वार्थ भाव से देते हैं।']],
'house' => [1 => ['name' => 'तनु भाव', 'topics' => 'स्वयं, शरीर, व्यक्तित्व, स्वास्थ्य और रूप', 'about' => 'प्रथम भाव कुंडली की नींव है। यह आपके शरीर और स्वास्थ्य, स्वभाव, दूसरों की नज़र में आपकी छवि और जीवन की सामान्य दिशा दिखाता है। बलवान प्रथम भाव और उसका स्वामी आत्मविश्वास, ऊर्जा और बाधाओं को पार करने की क्षमता देते हैं।'], 2 => ['name' => 'धन भाव', 'topics' => 'धन, परिवार, वाणी, भोजन, बचत और प्रारंभिक शिक्षा', 'about' => 'द्वितीय भाव संचित धन, पारिवारिक मूल्य, वाणी और भोजन की आदतें दिखाता है। यह बताता है कि आप कैसे बचत करते हैं, कैसे बोलते हैं और परिवार से कितना सहयोग मिलता है। यह प्रारंभिक शिक्षा और चेहरे का भी भाव है।'], 3 => ['name' => 'सहज भाव', 'topics' => 'साहस, भाई-बहन, संचार, छोटी यात्राएँ, कौशल और प्रयास', 'about' => 'तृतीय भाव आपके अपने प्रयास, साहस और पहल को दिखाता है। यह छोटे भाई-बहन, संचार, लेखन, मीडिया, छोटी यात्राओं और हाथों का कारक है। यहाँ के ग्रह ऊर्जा और अपने बल पर सफलता पाने की क्षमता देते हैं।'], 4 => ['name' => 'सुख भाव', 'topics' => 'माता, घर, संपत्ति, वाहन, सुख और मूल शिक्षा', 'about' => 'चतुर्थ भाव सुख का भाव है: माता, घर, भूमि, वाहन और आंतरिक शांति। यह मूल शिक्षा और भावनात्मक सुरक्षा भी दिखाता है। बलवान चतुर्थ भाव सुविधा, संपत्ति और सहयोगी पारिवारिक आधार देता है।'], 5 => ['name' => 'पुत्र भाव', 'topics' => 'संतान, बुद्धि, रचनात्मकता, प्रेम, पूर्व पुण्य और सट्टा', 'about' => 'पंचम भाव संतान, बुद्धि, रचनात्मकता और प्रेम संबंध दिखाता है। यह पूर्व पुण्य, यानी पिछले जन्मों के शुभ कर्मों का, और मंत्र, विद्या व सट्टे का भाव है। यह बताता है कि सौभाग्य आपकी ओर कितनी सहजता से आता है।'], 6 => ['name' => 'रिपु भाव', 'topics' => 'रोग, शत्रु, ऋण, विवाद, सेवा और प्रतिस्पर्धा', 'about' => 'षष्ठ भाव रोग, शत्रु, ऋण और प्रतिस्पर्धा तथा उन पर विजय पाने की आपकी शक्ति दिखाता है। यह दैनिक काम, सेवा, कर्मचारियों और पालतू जीवों का भी कारक है। यहाँ पाप ग्रह अच्छे योद्धा होते हैं और बाधाओं पर जीत दिलाते हैं।'], 7 => ['name' => 'कलत्र भाव', 'topics' => 'विवाह, जीवनसाथी, साझेदारी, व्यापार और जनसंपर्क', 'about' => 'सप्तम भाव विवाह और जीवनसाथी, व्यापारिक साझेदारी और सभी आमने-सामने के संबंध दिखाता है। यह जनसंपर्क, यात्रा और व्यापार भी बताता है। इसकी स्थिति जीवनसाथी के स्वभाव और वैवाहिक जीवन को दर्शाती है।'], 8 => ['name' => 'आयु भाव', 'topics' => 'आयु, अचानक घटनाएँ, रहस्य, विरासत, शोध और गुप्त विद्या', 'about' => 'अष्टम भाव आयु, अचानक बदलाव, छिपे विषयों और परिवर्तन का कारक है। यह विरासत, बीमा, जीवनसाथी का धन, शोध और गुप्त विद्या दिखाता है। यहाँ के ग्रह गहरी अंतर्दृष्टि के साथ-साथ अप्रत्याशित घटनाएँ भी ला सकते हैं।'], 9 => ['name' => 'धर्म भाव', 'topics' => 'भाग्य, पिता, गुरु, धर्म, उच्च शिक्षा और लंबी यात्राएँ', 'about' => 'नवम भाव भाग्य और धर्म का भाव है: पिता, गुरु, आस्था, उच्च शिक्षा और लंबी यात्राएँ। बलवान नवम भाव सौभाग्य, आशीर्वाद और मार्गदर्शन लाता है और आपके प्रयासों को फलदायी बनाता है।'], 10 => ['name' => 'कर्म भाव', 'topics' => 'करियर, व्यवसाय, प्रतिष्ठा, अधिकार, यश और कर्म', 'about' => 'दशम भाव कर्म और करियर का भाव है। यह आपका व्यवसाय, पद, अधिकार, यश और सार्वजनिक उपलब्धियाँ दिखाता है। यहाँ के ग्रह और दशमेश बताते हैं कि कैसा काम आपके अनुकूल है और आप कितना ऊपर उठते हैं।'], 11 => ['name' => 'लाभ भाव', 'topics' => 'लाभ, आय, बड़े भाई-बहन, मित्र, संपर्क और इच्छाएँ', 'about' => 'एकादश भाव लाभ का भाव है: आय, मुनाफ़ा, इच्छाओं की पूर्ति, मित्र और बड़े भाई-बहन। लगभग हर ग्रह यहाँ अच्छा फल देता है और संपर्कों व नेटवर्क के माध्यम से धन व सहयोग लाता है।'], 12 => ['name' => 'व्यय भाव', 'topics' => 'खर्च, हानि, विदेश, नींद, आध्यात्म और मोक्ष', 'about' => 'द्वादश भाव खर्च, हानि, विदेश, अस्पताल और एकांत, और साथ ही नींद, शैया सुख, दान और मोक्ष दिखाता है। यह बताता है कि आपकी ऊर्जा और धन कहाँ बाहर जाते हैं और आपकी आध्यात्मिक यात्रा का मार्ग क्या है।']],
'nak' => ['Ashwini' => ['अश्विनी कुमार', 'घोड़े का सिर', 'तेज़, ऊर्जावान और उपचारक, अश्विनी जातक गति और नई शुरुआत पसंद करते हैं। वे सहायक और युवा स्वभाव के होते हैं और अक्सर चिकित्सा या समस्याओं को जल्दी सुलझाने में निपुण होते हैं।'], 'Bharani' => ['यम', 'योनि', 'भरणी दृढ़ इच्छाशक्ति, रचनात्मकता और भारी ज़िम्मेदारी उठाने की क्षमता देती है। जातक भावुक और सत्यवादी होते हैं और जीवन के उतार-चढ़ाव को साहस से संभालते हैं।'], 'Krittika' => ['अग्नि', 'उस्तरा या ज्वाला', 'कृत्तिका तीक्ष्ण, शुद्ध करने वाली और दृढ़ है। जातक साहसी, स्पष्टवादी और रक्षक होते हैं, अपने और दूसरों के लिए ऊँचे मानदंड रखते हैं।'], 'Rohini' => ['ब्रह्मा', 'बैलगाड़ी', 'रोहिणी रचनात्मक, आकर्षक और उर्वर है, चंद्रमा का प्रिय नक्षत्र। जातक सौंदर्य, सुख और कला पसंद करते हैं और विकास व समृद्धि की प्रतिभा रखते हैं।'], 'Mrigashira' => ['सोम', 'हिरण का सिर', 'मृगशिरा जिज्ञासु, सौम्य और हमेशा खोज में रहने वाला है। जातक यात्रा, अध्ययन और खोज पसंद करते हैं, मिलनसार पर बेचैन होते हैं।'], 'Ardra' => ['रुद्र', 'आँसू की बूँद', 'आर्द्रा तीव्रता, बुद्धि और तूफ़ानों से होकर परिवर्तन लाती है। जातक तीक्ष्ण विचारक होते हैं जो कठिनाइयों के बाद और मज़बूत होते हैं।'], 'Punarvasu' => ['अदिति', 'धनुष और तरकश', 'पुनर्वसु नवीनीकरण और वापसी का नक्षत्र है। जातक दयालु, आशावादी और दार्शनिक होते हैं और हर झटके से उबर जाते हैं।'], 'Pushya' => ['बृहस्पति', 'गाय का थन', 'पुष्य सबसे पोषक और शुभ नक्षत्र है। जातक स्नेही, अनुशासित और धार्मिक होते हैं और दूसरों का विश्वास पाते हैं।'], 'Ashlesha' => ['नाग', 'कुंडली मारे सर्प', 'आश्लेषा गहरी अंतर्दृष्टि, चतुराई और सम्मोहक प्रभाव देता है। जातक समझदार और रणनीतिक होते हैं पर उन्हें संदेह से बचना चाहिए।'], 'Magha' => ['पितर', 'सिंहासन', 'मघा राजसी और पूर्वजों से जुड़ा है। जातक स्वाभिमानी, गरिमामय, परंपरा का सम्मान करने वाले और जन्मजात नेता होते हैं।'], 'Purva Phalguni' => ['भग', 'पलंग के आगे के पाये', 'पूर्वा फाल्गुनी आनंद, विश्राम, कला और प्रेम पसंद करता है। जातक आकर्षक, उदार और रचनात्मक होते हैं।'], 'Uttara Phalguni' => ['अर्यमा', 'पलंग के पीछे के पाये', 'उत्तरा फाल्गुनी संरक्षण और वचनों का नक्षत्र है। जातक सहायक, भरोसेमंद और दयालु होते हैं और साझेदारी में अच्छे रहते हैं।'], 'Hasta' => ['सविता', 'हाथ', 'हस्त हाथों का कौशल, बुद्धिमत्ता और साधन-संपन्नता देता है। जातक चतुर और परिश्रमी होते हैं और शिल्प व उपचार में निपुण होते हैं।'], 'Chitra' => ['विश्वकर्मा', 'चमकता रत्न', 'चित्रा दिव्य शिल्पी का नक्षत्र है। जातक रचनात्मक और स्टाइलिश होते हैं और डिज़ाइन व निर्माण में प्रतिभाशाली होते हैं।'], 'Swati' => ['वायु', 'हवा में झूमता अंकुर', 'स्वाति स्वतंत्र, लचीला और व्यापार-बुद्धि वाला है। जातक कूटनीतिक होते हैं, स्वतंत्रता पसंद करते हैं और व्यापार व संतुलन से सफल होते हैं।'], 'Vishakha' => ['इंद्र और अग्नि', 'विजय द्वार', 'विशाखा लक्ष्य-केंद्रित और दृढ़ है। जातक महत्वाकांक्षी और एकाग्र होते हैं और लगातार प्रयास के बाद सफलता पाते हैं।'], 'Anuradha' => ['मित्र', 'कमल', 'अनुराधा मित्रता और भक्ति का नक्षत्र है। जातक निष्ठावान और व्यवस्थित होते हैं और सहयोग से, अक्सर घर से दूर, सफल होते हैं।'], 'Jyeshtha' => ['इंद्र', 'कुंडल या छत्र', 'ज्येष्ठा वरिष्ठता और संरक्षण का नक्षत्र है। जातक ज़िम्मेदार और सक्षम नेता होते हैं, हालाँकि वे बोझ महसूस कर सकते हैं या रहस्यमय हो सकते हैं।'], 'Mula' => ['निऋति', 'जड़ों का गुच्छा', 'मूल चीज़ों की जड़ तक जाता है। जातक खोजी और दार्शनिक होते हैं और जीवन को नींव से फिर बना सकते हैं।'], 'Purva Ashadha' => ['आप (जल)', 'पंखा', 'पूर्वाषाढ़ा अजेय और शुद्ध करने वाला है। जातक आत्मविश्वासी और प्रभावशाली वक्ता होते हैं और अपने विश्वासों पर गर्व करते हैं।'], 'Uttara Ashadha' => ['विश्वेदेव', 'हाथी दाँत', 'उत्तराषाढ़ा स्थायी विजय देता है। जातक सिद्धांतवादी और ज़िम्मेदार होते हैं और स्थिर, स्थायी सफलता पाते हैं।'], 'Shravana' => ['भगवान विष्णु', 'कान', 'श्रवण सुनने और सीखने का नक्षत्र है। जातक ज्ञानी, जानकार और परंपरा का सम्मान करने वाले तथा अच्छे शिक्षक होते हैं।'], 'Dhanishta' => ['अष्ट वसु', 'ढोल', 'धनिष्ठा धन, लय और यश देता है। जातक संगीतप्रिय, उदार और ऊर्जावान होते हैं और समूहों में अच्छा करते हैं।'], 'Shatabhisha' => ['वरुण', 'खाली वृत्त', 'शतभिषा सौ वैद्यों का नक्षत्र है। जातक स्वतंत्र, निजता-प्रिय और वैज्ञानिक होते हैं और उपचार या शोध में प्रतिभाशाली होते हैं।'], 'Purva Bhadrapada' => ['अज एकपाद', 'तलवार', 'पूर्वा भाद्रपद तीव्र और आदर्शवादी है। जातक भावुक और आध्यात्मिक होते हैं और किसी उद्देश्य के लिए त्याग को तैयार रहते हैं।'], 'Uttara Bhadrapada' => ['अहिर्बुध्न्य', 'जुड़वाँ', 'उत्तरा भाद्रपद शांत, गहरा और ज्ञानी है। जातक धैर्यवान, अनुशासित और दयालु होते हैं और आध्यात्मिक झुकाव रखते हैं।'], 'Revati' => ['पूषा', 'मछली', 'रेवती सुरक्षित यात्रा और पोषण का नक्षत्र है। जातक सौम्य, उदार, रक्षक और कलाप्रिय होते हैं।']],
'dosha' => ['mangal' => 'मांगलिक दोष तब बनता है जब मंगल लग्न या चंद्रमा से कुछ विशेष भावों में हो। मंगल अग्नि ग्रह है और इन भावों में वैवाहिक जीवन में जल्दबाज़ी, बहस और टकराव ला सकता है। मंगल की राशि, समान स्थिति वाले साथी और लगभग अट्ठाईस वर्ष की आयु के बाद यह दोष प्रायः कम हो जाता है। संबंधों में धैर्य और नीचे दिए उपाय इसका व्यावहारिक उत्तर हैं।', 'kaal_sarp' => 'कालसर्प दोष तब बनता है जब सातों ग्रह राहु-केतु अक्ष के एक ओर हों। यह अचानक संघर्ष और देरी के दौर ला सकता है, जिनके बाद तेज़ उन्नति होती है। कई सफल लोगों की कुंडली में यह योग होता है; इसका प्रभाव संबंधित भावों और अन्य ग्रहों के बल पर निर्भर करता है।', 'sade_sati' => 'साढ़ेसाती चंद्र राशि से बारहवीं, पहली और दूसरी राशि पर शनि का साढ़े सात वर्ष का गोचर है। यह ज़िम्मेदारी, सीख और परिश्रम का समय है और अक्सर स्थायी परिपक्वता व उपलब्धि के साथ समाप्त होता है। ईमानदारी, अनुशासन और शनि के उपाय इसे बहुत हल्का कर देते हैं।', 'dhaiya' => 'शनि की ढैय्या चंद्र राशि से चौथी या आठवीं राशि में शनि का ढाई वर्ष का गोचर है। यह घर, स्वास्थ्य या काम पर दबाव ला सकती है और धैर्य व सोच-समझकर निर्णय माँगती है।', 'grahan' => 'ग्रहण दोष तब बनता है जब सूर्य या चंद्रमा के साथ राहु या केतु हो। यह आत्मविश्वास (सूर्य) या मन की शांति (चंद्रमा) पर बादल ला सकता है और उस भाव के विषयों में भ्रम पैदा कर सकता है। नियमित पूजा, दान और शांत दिनचर्या इसका प्रभाव कम करते हैं।', 'guru_chandal' => 'गुरु चांडाल दोष तब बनता है जब गुरु के साथ राहु या केतु हो। यह निर्णय क्षमता, आस्था और गुरुजनों के मार्गदर्शन को प्रभावित कर सकता है। बड़ों का सम्मान, स्वच्छ आदतें और गुरु के उपाय इसे संतुलन में लाते हैं।', 'kemadruma' => 'केमद्रुम दोष तब बनता है जब चंद्रमा के दोनों ओर कोई ग्रह न हो। यह अकेलेपन या आर्थिक उतार-चढ़ाव के दौर ला सकता है। अन्य बलवान ग्रह अक्सर इसे निरस्त कर देते हैं और चंद्रमा के उपाय सहायक होते हैं।', 'pitra' => 'पितृ दोष पूर्वजों के अधूरे कर्मों की ओर संकेत करता है। यह देरी, पारिवारिक प्रगति में बाधा या प्रयास के बावजूद फल न मिलने के रूप में दिख सकता है। श्राद्ध, ज़रूरतमंदों को भोजन और बड़ों का सम्मान इसके पारंपरिक उपाय हैं।'],
'dignity' => ['exalted' => '{planet} यहाँ उच्च का है, अपनी सबसे बलवान स्थिति में, और सहजता से श्रेष्ठ फल देता है।', 'own' => '{planet} अपनी राशि में है, सहज और बलवान, और अपने भाव के विषयों की रक्षा करता है।', 'debilitated' => '{planet} यहाँ नीच का है, अपनी सबसे निर्बल स्थिति में, इसलिए इसके विषयों में अतिरिक्त प्रयास और नीचे दिए उपाय ज़रूरी हैं।', '' => '{planet} सम राशि में है, इसलिए इसके फल मुख्यतः भाव, स्वामित्व और चल रही दशा पर निर्भर करते हैं।'],
't' => ['cover_title' => 'जन्म कुंडली एवं जीवन रिपोर्ट', 'cover_sub' => 'वैदिक ज्योतिष · लाल किताब · उपाय', 'prepared_for' => 'के लिए तैयार', 'generated' => 'तैयार करने की तिथि', 'contents' => 'विषय-सूची', 'ch_intro' => 'इस रिपोर्ट के बारे में', 'ch_birth' => 'जन्म विवरण और जन्म पंचांग', 'ch_charts' => 'जन्म कुंडली', 'ch_vargas' => 'वर्ग कुंडलियाँ', 'ch_lagna' => 'आपका लग्न', 'ch_moon' => 'आपकी चंद्र राशि', 'ch_nak' => 'आपका जन्म नक्षत्र', 'ch_planets' => 'आपकी कुंडली के नौ ग्रह', 'ch_houses' => 'बारह भाव', 'ch_life' => 'जीवन के क्षेत्र', 'ch_yoga' => 'योग: विशेष ग्रह संयोग', 'ch_dosha' => 'दोष और कर्म-ऋण', 'ch_dasha' => 'विंशोत्तरी दशा: आपकी ग्रह दशाएँ', 'ch_current' => 'आपकी वर्तमान दशा', 'ch_transit' => 'वर्तमान गोचर', 'ch_varsh' => 'वर्षफल: यह वर्ष', 'ch_months' => 'मास-दर-मास मार्गदर्शन', 'ch_remedy' => 'उपाय', 'ch_lucky' => 'शुभ कारक', 'ch_gloss' => 'शब्दावली', 'ch_note' => 'महत्वपूर्ण सूचना', 'intro1' => 'यह रिपोर्ट आपकी जन्म तिथि, समय और स्थान से तैयार की गई है। आपकी जन्म कुंडली निरयन राशिचक्र और लाहिड़ी अयनांश से बनाई गई है, जो पूरे भारत में मानक है, और जन्म के क्षण के लिए सूर्य, चंद्रमा, ग्रहों तथा राहु-केतु की स्थिति सटीक रूप से निकाली गई है।', 'intro2' => 'इसके बाद कुंडली को शास्त्रीय वैदिक (पाराशरी) सिद्धांतों और लाल किताब के व्यावहारिक नियमों से पढ़ा गया है। हर ग्रह को उसकी राशि, भाव, बल, नक्षत्र और स्वामित्व वाले भावों से परखा गया है। समय निर्धारण के लिए विंशोत्तरी दशा का उपयोग हुआ है, और वर्तमान गोचर व वर्षफल बताते हैं कि अभी क्या सक्रिय है।', 'intro3' => 'ज्योतिष प्रवृत्तियाँ दिखाता है, अटल भाग्य नहीं। आपका अपना प्रयास, चुनाव और अच्छे कर्म तय करते हैं कि ये प्रवृत्तियाँ कैसे फलित होंगी। इस रिपोर्ट की शक्तियों को उपयोग करने के अवसर और चुनौतियों को सावधानी व सरल उपायों से संभालने के क्षेत्र के रूप में पढ़ें।', 'intro4' => 'रिपोर्ट कैसे पढ़ें: पहले अपना लग्न, चंद्र राशि और जन्म नक्षत्र पढ़ें, जो आपका स्वभाव बताते हैं। फिर जीवन के हर क्षेत्र के विस्तार के लिए ग्रह और भाव पढ़ें। दशा वाले अध्याय बताते हैं कि घटनाएँ कब होने की संभावना है, और उपाय वाला अध्याय आज से शुरू करने योग्य व्यावहारिक कदम देता है।', 'birth_intro' => 'जन्म के क्षण का पंचांग उस दिन की गुणवत्ता बताता है। वार, तिथि, नक्षत्र, योग और करण मिलकर उस समय का स्वभाव दिखाते हैं जिसमें आपका जन्म हुआ, और इनका उपयोग नामकरण, मुहूर्त और मिलान में होता है।', 'charts_intro' => 'लग्न कुंडली (D1) मुख्य जन्म कुंडली है और पूरा जीवन दिखाती है। नवांश (D9) ग्रहों का आंतरिक बल, विवाह और जीवन का उत्तरार्ध दिखाता है। चंद्र कुंडली चंद्र राशि को पहला भाव मानती है और मन की दृष्टि से जीवन का अनुभव दिखाती है।', 'vargas_intro' => 'वर्ग कुंडलियाँ हर राशि को छोटे भागों में बाँटकर जीवन के एक क्षेत्र को विस्तार से देखती हैं: धन के लिए D2, भाई-बहन के लिए D3, संतान के लिए D7, विवाह के लिए D9, करियर के लिए D10, माता-पिता के लिए D12 आदि। जो ग्रह D1 और संबंधित वर्ग दोनों में बलवान हो, वह सबसे विश्वसनीय फल देता है।', 'lagna_lord' => 'आपका लग्नेश {lord} {h} भाव में {sign} राशि में स्थित है। लग्नेश कुंडली का कप्तान है, इसलिए यह आपके व्यक्तित्व, स्वास्थ्य और जीवन की दिशा को {topics} से जोड़ता है। {q}', 'moon_intro' => 'आपकी चंद्र राशि {sign} है और चंद्रमा आपके {h} भाव में है। राशि का उपयोग दैनिक और मासिक राशिफल, साढ़ेसाती और कई महत्वपूर्ण निर्णयों में होता है।', 'nak_intro' => 'आपका जन्म {nak} नक्षत्र के {pada} चरण में हुआ। इसका स्वामी ग्रह {lord}, देवता {deity} और प्रतीक {symbol} है।', 'nak_dasha' => 'क्योंकि {lord} आपके जन्म नक्षत्र का स्वामी है, आपका जीवन {lord} की महादशा से शुरू हुआ। आगे की सभी दशाओं का क्रम इसी से चलता है, जैसा दशा अध्याय में दिखाया गया है।', 'nak_pada' => 'जिस चरण में आपका जन्म हुआ, वह {navamsa} नवांश का रंग जोड़ता है, जिससे इस नक्षत्र के गुण आपमें विशेष रूप से प्रकट होते हैं।', 'p_place' => 'आपकी कुंडली में {planet} {sign} राशि में {h} भाव ({hname}) में है, जो {topics} का भाव है। {sign_nature}', 'p_lords' => '{planet} आपके {houses} भाव का स्वामी है, इसलिए यह {topics} के विषयों को उस {h} भाव में ले आता है जहाँ यह बैठा है।', 'p_nak' => 'यह {nak} नक्षत्र के {pada} चरण में है, जिसका स्वामी {lord} है। {nak_text}', 'p_retro' => '{planet} वक्री है, जिससे इसकी ऊर्जा भीतर की ओर मुड़ती है: इसके फल देरी या दोबारा प्रयास के बाद, पर गहरी समझ के साथ मिल सकते हैं।', 'p_combust' => '{planet} अस्त है, यानी सूर्य के बहुत निकट, जिससे इसके स्वतंत्र फल कमज़ोर होते हैं; इसके विषयों में सचेत देखभाल ज़रूरी है।', 'p_score' => 'आपकी कुंडली में {planet} का कुल बल: {score}/100 ({label})।', 'p_lk' => 'लाल किताब के अनुसार', 'p_rem' => '{planet} के उपाय', 'p_facts' => 'ग्रह एक नज़र में', 'f_day' => 'वार', 'f_color' => 'रंग', 'f_gem' => 'रत्न', 'f_metal' => 'धातु', 'f_grain' => 'दान का अन्न', 'f_deity' => 'देवता', 'f_mantra' => 'मंत्र', 'f_number' => 'अंक', 'h_sign' => 'आपकी कुंडली में इस भाव पर {sign} राशि है, जिसका स्वामी {lord} है। {sign_nature}', 'h_lord' => 'इस भाव का स्वामी {lord} आपके {h2} भाव में है, जो {topics2} का भाव है। यह इस भाव के विषयों को {topics2} से जोड़ता है।', 'h_lord_good' => 'यह सहायक स्थिति है, इसलिए इस भाव के विषय प्रायः अच्छी प्रगति करते हैं और सहयोग मिलता है।', 'h_lord_hard' => 'स्वामी चुनौती वाले भाव में होने से फल प्रयास और धैर्य के बाद मिलते हैं; {lord} के उपाय सहायक होंगे।', 'h_lord_mid' => 'फल निरंतर प्रयास और सही समय से मिलते हैं, विशेषकर {lord} की दशा में।', 'h_occ' => 'इस भाव में ग्रह: {list}। इनका स्वभाव इन विषयों को सीधे प्रभावित करता है।', 'h_empty' => 'इस भाव में कोई ग्रह नहीं है, इसलिए इसके फल मुख्यतः इसके स्वामी {lord}, इस पर पड़ने वाली दृष्टियों और चल रही दशा पर निर्भर करते हैं।', 'h_occ_one' => 'यहाँ {planet} अपने विषय इस भाव में लाता है: {sig}', 'life_house' => 'ज्योतिष में यह क्षेत्र आपके {h} भाव और उसके स्वामी {lord} से देखा जाता है, जो {h2} भाव में स्थित है।', 'yoga_present' => 'यह योग आपकी कुंडली में बन रहा है।', 'yoga_absent' => 'जाँचे गए पर न बने योग', 'yoga_rule' => 'कैसे बनता है', 'yoga_effect' => 'क्या फल देता है', 'yoga_use' => 'योग संभावना दिखाते हैं। वे उन्हें बनाने वाले ग्रहों की दशा या अंतर्दशा में, और जब गोचर उनका साथ दे, तब पूरा फल देते हैं। अच्छा आचरण और इन ग्रहों के उपाय योग को फलित होने में मदद करते हैं।', 'dosha_present' => 'आपकी कुंडली में उपस्थित', 'dosha_absent' => 'उपस्थित नहीं', 'dosha_effects' => 'संभावित प्रभाव', 'dosha_remedy' => 'उपाय', 'rin_intro' => 'लाल किताब पारिवारिक वंश से चले आ रहे कर्म-ऋणों का वर्णन करती है। ऋण विशेष भावों में विशेष ग्रहों से दिखता है और परिवार के सामूहिक उपाय से उतरता है।', 'd_period' => '{from} से {to} · {years} वर्ष · आयु {a1} से {a2}', 'd_place' => 'आपकी कुंडली में {lord} {sign} राशि में {h} भाव में है और {houses} भाव का स्वामी है, इसलिए यह अवधि {topics} के विषयों को आगे लाती है।', 'd_pos' => 'अच्छा रहने की संभावना', 'd_neg' => 'सावधानी चाहिए', 'd_ad' => 'अंतर्दशाएँ', 'd_now' => 'वर्तमान', 'cur_intro' => 'अभी आप {md} की महादशा ({md_to} तक) और {ad} की अंतर्दशा ({ad_to} तक) में हैं।', 'cur_ad' => 'अंतर्दशा स्वामी {ad} मुख्य दशा में अपना रंग जोड़ता है।', 'tr_intro' => 'गोचर ग्रहों की वर्तमान स्थिति है, जिसे आपकी चंद्र राशि से गिना जाता है। शनि, गुरु, राहु और केतु जैसे धीमे ग्रह महीनों या वर्षों की पृष्ठभूमि बनाते हैं, जबकि सूर्य, बुध, शुक्र और मंगल हर सप्ताह माहौल बदलते हैं।', 'tr_row' => '{planet} अभी {sign} राशि में गोचर कर रहा है, जो आपकी चंद्र राशि से {hm} और लग्न से {hl} भाव है।', 'varsh_intro' => 'वर्षफल (वार्षिक कुंडली) हर वर्ष उस क्षण के लिए बनाई जाती है जब सूर्य अपनी जन्म स्थिति पर लौटता है। यह एक जन्मदिन से अगले जन्मदिन तक के वर्ष के विषय दिखाती है। मुंथा बताता है कि इस वर्ष जीवन का कौन-सा क्षेत्र प्रमुख रहेगा।', 'month_intro' => 'आगे के पृष्ठ अगले बारह महीनों में से हर महीने के लिए मार्गदर्शन देते हैं, जो आपकी कुंडली पर ग्रहों के गोचर और चल रही दशा पर आधारित है। अनुकूल महीनों में महत्वपूर्ण काम शुरू करें और सावधानी वाले महीनों में योजना, काम पूरा करने और उपायों पर ध्यान दें।', 'm_score' => 'कुल अंक: {score}/100 · {label}', 'rem_intro' => 'उपाय वे सरल कर्म हैं जो ग्रहों के कठिन प्रभाव कम करते हैं और सहायक प्रभाव बढ़ाते हैं। प्राथमिक उपायों से शुरू करें, इन्हें श्रद्धा और नियमितता से करें, और याद रखें कि अच्छा आचरण हर उपाय की नींव है।', 'rem_priority' => 'आपके लिए प्राथमिक उपाय', 'rem_life' => 'आजीवन लाल किताब उपाय', 'rem_gems' => 'रत्न', 'rem_mantra' => 'सहयोग चाहने वाले ग्रहों के मंत्र', 'rem_gem_note' => 'रत्न कुछ दिन आज़माकर और हो सके तो ज्योतिषी से सलाह लेकर ही पहनें। अच्छी गुणवत्ता का प्राकृतिक, बिना उपचार का रत्न चुनें, सही धातु में जड़वाएँ और सही दिन ग्रह के मंत्र से अभिमंत्रित करें।', 'lucky_intro' => 'ये शुभ कारक आपकी कुंडली के सबसे सहायक ग्रहों से लिए गए हैं। इनका उपयोग महत्वपूर्ण शुरुआतों में करें: साक्षात्कार, अनुबंध, खरीदारी और यात्रा।', 'gloss' => [['लग्न', 'जन्म के समय पूर्वी क्षितिज पर उदित राशि। यह प्रथम भाव बनाती है और शरीर, व्यक्तित्व व जीवन की दिशा बताती है।'], ['राशि (चंद्र राशि)', 'जन्म के समय चंद्रमा जिस राशि में था। यह मन और भावनाएँ बताती है और राशिफल में उपयोग होती है।'], ['नक्षत्र', '13°20\' के 27 चंद्र नक्षत्रों में से एक। जन्म के समय चंद्रमा का नक्षत्र जन्म नक्षत्र है।'], ['भाव', 'कुंडली के बारह भागों में से एक, जो जीवन के विशेष क्षेत्रों का कारक है।'], ['दशा', 'ग्रह की अवधि। विंशोत्तरी पद्धति 120 वर्ष के चक्र को नौ ग्रहों में बाँटती है।'], ['अंतर्दशा', 'महादशा के भीतर किसी दूसरे ग्रह की उप-अवधि।'], ['गोचर', 'आपकी जन्म कुंडली पर ग्रहों की वर्तमान चाल।'], ['योग', 'ग्रहों का विशेष संयोग जो विशेष फल देता है।'], ['दोष', 'कठिन ग्रह संयोग से बना कष्ट, जो प्रायः उपायों से कम होता है।'], ['वर्ग', 'जीवन के एक क्षेत्र को विस्तार से देखने वाली कुंडली, जैसे नवांश (D9)।'], ['उच्च / नीच', 'वह राशि जहाँ ग्रह सबसे बलवान / सबसे निर्बल होता है।'], ['वक्री', 'पृथ्वी से उल्टी चलती दिखने वाली ग्रह; इसके फल देरी या दोबारा प्रयास से मिलते हैं।'], ['उपाय', 'ग्रह को संतुलित करने के लिए सरल कर्म, दान, मंत्र या अनुशासन।']], 'note' => 'यह रिपोर्ट आपके जन्म विवरण पर वैदिक ज्योतिष और लाल किताब के शास्त्रीय नियम लागू करके बनाई गई है। यह मार्गदर्शन और आत्म-समझ के लिए है। यह चिकित्सा, कानूनी या आर्थिक सलाह का विकल्प नहीं है और किसी परिणाम की गारंटी नहीं है। हमेशा अपने विवेक से काम लें और महत्वपूर्ण निर्णयों के लिए योग्य विशेषज्ञों से सलाह लें।', 'house_n' => ['पहले', 'दूसरे', 'तीसरे', 'चौथे', 'पाँचवें', 'छठे', 'सातवें', 'आठवें', 'नौवें', 'दसवें', 'ग्यारहवें', 'बारहवें'], 'table_planet' => 'ग्रह', 'table_sign' => 'राशि', 'table_house' => 'भाव', 'table_deg' => 'अंश', 'table_nak' => 'नक्षत्र', 'table_status' => 'स्थिति', 'years' => 'वर्ष', 'strong' => 'बलवान', 'average' => 'सामान्य', 'weak' => 'निर्बल'],
